INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Satya Priya Mahathero$b$, NULL, DATE '2019-10-04', $b$Upa-Sangharaj Satya Priya Mahathero (Bidhu Bhiushan Barua, (born on 10 June 1930, Died on 4 October 2019) Ramu Upazilla, Cox's Bazar, Bangladesh) was a Bangladeshi Buddhist monk, writer, religious leader and social worker. He is mostly known for received the highest honourable national prize of Bangladesh "Ekushey Padak". He was the President of Bangladesh Sangharaj Bhikkhu Mahasava. He was the first translator & writer of 'The Chullyabarga' which is an important part of the Buddhist holy book Tripitaka.

Source: Wikipedia — https://en.wikipedia.org/wiki/Satya_Priya_Mahathero$b$, 'en', NULL, $b$Buddhist monk$b$, $b$Cox's Bazar District$b$, $b$Dhaka$b$);
INSERT INTO people (id, name, birth_date, death_date, bio, lang, photo_url, occupation, birth_place, death_place) VALUES (gen_random_uuid(), $b$Neem Chandra Bhowmik$b$, NULL, DATE '2026-10-04', $b$Neem Chandra Bhowmik (Bengali: নিমচন্দ্র ভৌমিক; died 4 October 2026) was a Bangladeshi physicist and diplomat who was a professor in the Department of Applied Physics at the University of Dhaka and a leader of the Hindu minority community in Bangladesh. He was the Ambassador of Bangladesh to Nepal with a controversial term. He was the president of Bangladesh Hindu Buddhist Christian Unity Council.

Source: Wikipedia — https://en.wikipedia.org/wiki/Neem_Chandra_Bhowmik$b$, 'en', NULL, $b$Professor, Physicist$b$, NULL, $b$Dhaka$b$);
